@startuml

class Song {
  + title : string
  + year : int
  + length : time
  + genre : string
}

class Artist {
  + name : string
  + dateOfBirth : date
  + websiteURL : string
}

class User {
  + userID : int
  + name : string
  + address : string
}

class RegularUser {
}

class BusinessUser {
  + VATNumber : string
}

class Single {
}

class Hit {
  + trackNumber : int
}

class Album {
  + title : string
}

class Suggestion {
  + similarityScore : float
}

class Purchase {
  + purchaseDate : datetime
}

User --|> RegularUser
User --|> BusinessUser

Artist "1" -- "*" Song
RegularUser "1" -- "*" Purchase
Purchase "*" -- "1" Single
Purchase "*" -- "1" Album

BusinessUser "1" -- "*" Song
Single --|> Song
Hit --|> Song

Album "1" *-- "1..*" Hit

RegularUser "1" -- "*" Album
RegularUser "1" -- "*" Suggestion
RegularUser "1" -- "*" RegularUser : similarBehavior

@enduml

